const DECK_WEB_EXTRA = [
  { id: 'wx1',
    q: 'Опишите критический путь рендеринга детально. Что его блокирует?',
    a: `<p>Браузер получает HTML и начинает инкрементальный парсинг. Дальше: HTML → DOM, CSS → CSSOM, слияние в render tree (без <code>display: none</code>), layout (геометрия), paint (списки команд рисования), composite (слои складываются, часто на GPU).</p>
    <ul><li><strong>CSS блокирует рендеринг</strong>: пока не загружен и не разобран весь подходящий по <code>media</code> CSS, render tree не построить. Отсюда приём <code>media="print"</code> для некритичных файлов.</li>
    <li><strong>Синхронный script блокирует парсинг</strong>, потому что может вызвать <code>document.write</code>. Более того, скрипт ждёт применения предшествующего CSS (ему может понадобиться <code>getComputedStyle</code>) — поэтому CSS косвенно блокирует и JS.</li>
    <li><code>defer</code> — скачивание параллельно, выполнение после парсинга в порядке объявления; <code>async</code> — выполнение сразу по готовности, порядок не гарантирован; <code>type="module"</code> отложен по умолчанию.</li>
    <li><strong>Preload scanner</strong> — второй облегчённый парсер, который заранее находит ресурсы дальше по документу и начинает их качать даже пока основной парсер заблокирован. Именно поэтому картинки, вставленные из JS или через CSS <code>background</code>, обнаруживаются поздно — это частая причина плохого LCP.</li>
    <li>Дополнительно рендер могут блокировать: шрифты через FOIT, <code>blocking="render"</code>, синхронные XHR и большие инлайновые скрипты.</li></ul>`,
    tip: 'Упоминание preload scanner и того, что он не видит ресурсы из JS/CSS, — сильный ответ про LCP-изображения.' },

  { id: 'wx2',
    q: 'Чем отличаются preload, prefetch, preconnect, dns-prefetch и modulepreload?',
    a: `<p>Все это resource hints, но они решают разные задачи и по-разному дороги.</p>
    <ul><li><code>dns-prefetch</code> — только DNS-резолв. Дёшево, работает в старых браузерах, полезно для доменов, которые понадобятся <strong>возможно</strong>.</li>
    <li><code>preconnect</code> — DNS + TCP + TLS. Экономит 100–300 мс на медленных сетях, но держит соединение и тратит ресурсы; больше 2–4 preconnect обычно вредят. Обязателен <code>crossorigin</code> для шрифтов и любых CORS-запросов, иначе откроется <strong>второе</strong> соединение и hint пропадёт зря.</li>
    <li><code>preload</code> — реальная загрузка ресурса с высоким приоритетом для <strong>текущей</strong> страницы. Требует <code>as</code> (иначе двойная загрузка) и <code>crossorigin</code> для шрифтов. Если ресурс не использован в течение нескольких секунд — предупреждение в консоли и потраченная полоса.</li>
    <li><code>modulepreload</code> — preload для ES-модуля: не только качает, но и <strong>парсит и строит граф зависимостей</strong>, рекурсивно подгружая импорты. Обычная <code>preload as="script"</code> этого не делает.</li>
    <li><code>prefetch</code> — загрузка с низшим приоритетом для <strong>будущей</strong> навигации, кладётся в кеш. Дешёвая спекуляция, но на мобильном трафике её надо ограничивать (<code>navigator.connection.saveData</code>).</li></ul>
    <p>Главный риск — переиспользование: каждый preload отнимает полосу у по-настоящему критичного ресурса и может ухудшить LCP.</p>`,
    code: `<link rel="preconnect" href="https://cdn.site.ru" crossorigin>
<link rel="preload" as="font" type="font/woff2" href="/f.woff2" crossorigin>
<link rel="modulepreload" href="/assets/route-checkout.js">`,
    tip: 'Забытый crossorigin у preload шрифта — классическая ошибка, приводящая к двойной загрузке. Назовите её.' },

  { id: 'wx3',
    q: 'Как браузер расставляет приоритеты загрузки и что делает fetchpriority?',
    a: `<p>У каждого запроса есть внутренний приоритет (Highest/High/Medium/Low/Lowest), который влияет и на порядок отправки, и на распределение полосы в HTTP/2. Эвристики примерно такие: HTML и CSS — highest; шрифты — high; синхронные скрипты в head — high; <code>async</code>/<code>defer</code>-скрипты — low; XHR/fetch — high; изображения — <strong>low, пока не станет известно, что они в вьюпорте</strong>, после layout их повышают; <code>loading="lazy"</code> — very low; prefetch — lowest.</p>
    <ul><li>Ключевая проблема: LCP-картинка изначально low, и её повышение происходит только после layout — то есть после CSS. Отсюда классический <code>fetchpriority="high"</code> на герой-изображении.</li>
    <li><code>fetchpriority</code> принимает <code>high</code>, <code>low</code>, <code>auto</code> и работает на <code>img</code>, <code>link</code>, <code>script</code>, <code>iframe</code> и в <code>fetch()</code>. Это <strong>подсказка</strong>: браузер сам решает, менять ли приоритет.</li>
    <li>Полезно и <strong>понижение</strong>: <code>fetchpriority="low"</code> для изображений карусели ниже первого слайда, для аналитики, для превью в оффскрине.</li>
    <li>Антипаттерн — «поднять всё»: относительный порядок не меняется, а конкуренция за полосу растёт. Приоритеты имеют смысл только как относительные.</li>
    <li>Проверять — колонка Priority в Network (её надо включить) и трейс в DevTools.</li></ul>`,
    code: `<img src="/hero.avif" fetchpriority="high" width="1200" height="630" alt="">`,
    tip: 'Объясните механику: картинка low до layout — именно поэтому fetchpriority на LCP-изображении даёт реальный выигрыш.' },

  { id: 'wx4',
    q: 'Что такое Speculation Rules API и чем он лучше ручного prefetch?',
    a: `<p>Это декларативный JSON в <code>&lt;script type="speculationrules"&gt;</code>, где вы описываете, какие URL стоит <strong>prefetch</strong> (скачать документ) или <strong>prerender</strong> (полностью отрендерить в скрытой вкладке, включая исполнение JS). При переходе страница показывается мгновенно, LCP фактически нулевой.</p>
    <ul><li>Правила бывают <code>list</code> (явный список URL) и <code>document</code> (селекторы ссылок плюс условия), с <code>eagerness</code>: <code>immediate</code>, <code>eager</code>, <code>moderate</code> (по hover ~200 мс), <code>conservative</code> (по нажатию кнопки мыши). Браузер сам ограничивает количество и учитывает Save-Data и память.</li>
    <li>Отличие от <code>&lt;link rel="prefetch"&gt;</code>: браузер управляет эвристиками и лимитами, prerender исполняет JS, и всё это работает для cross-document навигации без ручного кода.</li>
    <li><strong>Опасность prerender</strong>: страница действительно выполняется — аналитика может засчитать просмотр, который не случился, а сайд-эффекты (POST, счётчики) выполнятся зря. Лечится <code>document.prerendering</code>, событием <code>prerenderingchange</code> и Page Visibility.</li>
    <li>Prerender не сработает для URL, требующих авторизации в другом состоянии, для ответов с <code>Cache-Control: no-store</code> и при конфликте с CSP.</li>
    <li>В связке с cross-document view transitions даёт MPA, неотличимую от SPA.</li></ul>`,
    code: `<script type="speculationrules">
{"prerender":[{"where":{"href_matches":"/product/*"},"eagerness":"moderate"}]}
</script>`,
    tip: 'Проблема с двойным подсчётом аналитики при prerender — то, что реально ловят в проде.' },

  { id: 'wx5',
    q: 'Опишите жизненный цикл Service Worker и проблему обновления.',
    a: `<p>Цикл: <code>register</code> → <code>install</code> (обычно прекеш) → <code>waiting</code> → <code>activate</code> (очистка старых кешей) → <code>controlling</code>. Ключевая деталь: новый SW уходит в <strong>waiting</strong> и не активируется, пока открыта хоть одна вкладка со старым, потому что два разных SW не должны контролировать одну версию приложения. Reload вкладки этого не решает — нужно полное закрытие всех вкладок.</p>
    <ul><li><code>skipWaiting()</code> активирует новый SW сразу, <code>clients.claim()</code> захватывает уже открытые страницы. Но применять их вслепую опасно: у пользователя уже загружен старый JS-чанк, а новый SW отдаёт новый манифест — получаем ошибки динамического импорта отсутствующего чанка.</li>
    <li>Правильный паттерн — <strong>спросить пользователя</strong>: показать тост «Доступна новая версия», по клику отправить <code>postMessage</code> с <code>SKIP_WAITING</code> и перезагрузить страницу по событию <code>controllerchange</code> (с защитой от цикла).</li>
    <li>Сам файл SW браузер перепроверяет минимум раз в 24 часа и при навигации; он не должен кешироваться надолго (<code>Cache-Control: max-age=0</code>), иначе обновление залипнет.</li>
    <li>Аварийный выход обязателен: код, умеющий <code>registration.unregister()</code> и очистить кеши, — иначе битый SW «замуровывает» пользователей на вашем домене.</li></ul>`,
    code: `self.addEventListener('message', (e) => {
  if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting();
});`,
    tip: 'Обязательно скажите про kill switch — история про залипший SW есть у всех, кто его внедрял.' },

  { id: 'wx6',
    q: 'Какие стратегии кеширования в Service Worker и когда какую применять?',
    a: `<p>Пять базовых стратегий:</p>
    <ul><li><strong>Cache first</strong> — для иммутабельных ресурсов с хешем в имени. Быстро и офлайн, но требует правильного версионирования.</li>
    <li><strong>Network first</strong> — для API и HTML, где свежесть важнее скорости; с таймаутом на сеть и фолбэком в кеш.</li>
    <li><strong>Stale-while-revalidate</strong> — отдать из кеша немедленно и обновить в фоне. Лучший компромисс для аватарок, списков, некритичного контента; цена — пользователь видит данные на один запрос устаревшими.</li>
    <li><strong>Cache only</strong> — прекешированная оболочка; <strong>network only</strong> — всё, что нельзя кешировать (аналитика, платежи).</li></ul>
    <p>Важные практические моменты:</p>
    <ul><li>Никогда не кешировать ответы с приватными данными в общем кеше: SW-кеш живёт на origin, и на общем устройстве это утечка. Разделяйте кеш по пользователю или не кешируйте вовсе.</li>
    <li>Кешировать только успешные ответы (<code>response.ok</code>) и не кешировать opaque-ответы бездумно — они занимают в квоте гораздо больше реального размера.</li>
    <li>Навигационные запросы обрабатывают через navigation preload, иначе старт SW добавляет задержку к каждому переходу.</li>
    <li>Писать всё вручную обычно не стоит — Workbox покрывает стратегии, expiration и precache-манифест.</li></ul>`,
    tip: 'Риск утечки приватных данных через SW-кеш — тема, которую почти никто не поднимает, и она сразу запоминается.' },

  { id: 'wx7',
    q: 'Что делает веб-приложение PWA и когда это оправдано?',
    a: `<p>Технический минимум: HTTPS, web app manifest (<code>name</code>, <code>icons</code> 192 и 512, <code>start_url</code>, <code>display</code>) и зарегистрированный Service Worker с обработчиком <code>fetch</code>. Это даёт установку на домашний экран, запуск без адресной строки и офлайн.</p>
    <ul><li>Возможности сверх этого: Push (на iOS — только для установленных PWA, с 16.4), Background Sync, Badging, File Handling, Web Share, Screen Wake Lock, App Shortcuts.</li>
    <li>Реальные ограничения на iOS: жёсткая квота хранилища и удаление данных после ~7 дней неиспользования, отсутствие ряда API, установка только через Share → Add to Home Screen.</li>
    <li>Установку нельзя вызвать программно: событие <code>beforeinstallprompt</code> надо перехватить, сохранить и показать свой UI по жесту пользователя.</li>
    <li>Оправдано, когда есть повторные заходы и ценность офлайна: расписания, заметки, чек-листы, торговые точки, страны с плохой связью. Не оправдано для лендингов и редко посещаемых сайтов — там SW добавляет только риск.</li></ul>
    <p>Стоит помнить, что SW — это ещё и слой, который может <strong>сломать</strong> прод: любая ошибка в нём кешируется у пользователей надолго.</p>`,
    tip: 'Честная оценка «PWA не нужен лендингу, а SW — это риск» звучит взрослее, чем восторг по поводу офлайна.' },

  { id: 'wx8',
    q: 'Когда реально нужен Web Worker и в чём его цена?',
    a: `<p>Worker нужен, когда есть <strong>длительные синхронные вычисления</strong>, блокирующие main thread и, соответственно, INP: парсинг больших JSON и CSV, обработка изображений, криптография, диффы, поиск и фильтрация по десяткам тысяч записей, синтаксическая подсветка, WASM-нагрузка.</p>
    <ul><li>Цена — <strong>сериализация</strong>: структурированное клонирование больших объектов может стоить дороже самих вычислений. Спасают <code>Transferable</code> (ArrayBuffer передаётся без копии), SharedArrayBuffer (требует COOP/COEP-заголовков) и OffscreenCanvas.</li>
    <li>В воркере нет DOM, <code>window</code> и localStorage; доступны fetch, IndexedDB, WebSocket, Cache API.</li>
    <li>Асинхронность сама по себе не освобождает поток: <code>await</code> вокруг тяжёлого цикла ничего не даёт. Worker решает именно проблему CPU, а не ожидания I/O.</li>
    <li>Практика: воркер оправдан от нескольких десятков миллисекунд работы; для меньшего дешевле разбить задачу на чанки с yield.</li>
    <li>Удобные обёртки — Comlink; для React есть паттерн «воркер как источник данных» плюс подписка.</li></ul>`,
    code: `const w = new Worker(new URL('./parse.worker.ts', import.meta.url), { type: 'module' });
w.postMessage(buffer, [buffer]); // transfer, без копирования`,
    tip: 'Фраза «стоимость передачи данных может съесть весь выигрыш» показывает реальный опыт, а не теорию.' },

  { id: 'wx9',
    q: 'Как правильно разбивать длинные задачи: requestIdleCallback, scheduler API, yielding?',
    a: `<p>Задача дольше 50 мс считается long task и напрямую портит INP: браузер не может обработать ввод, пока занят main thread. Инструменты разбивки:</p>
    <ul><li><code>setTimeout(fn, 0)</code> — старый способ уступить поток; работает, но задача попадает в очередь макротасков без приоритета и с минимальным клампом.</li>
    <li><code>requestIdleCallback</code> — выполнить в простое, с <code>timeout</code> как гарантией. Подходит для аналитики, префетча, логов. Не подходит для UI-работы: idle может не наступить долго, а в Safari поддержка появилась поздно.</li>
    <li><code>scheduler.postTask(fn, { priority })</code> — приоритеты <code>user-blocking</code>, <code>user-visible</code>, <code>background</code>, отменяемость через <code>TaskSignal</code>. Это правильный современный планировщик.</li>
    <li><code>await scheduler.yield()</code> — уступить поток и <strong>вернуться с приоритетом выше</strong> обычных задач: продолжение не окажется в конце очереди, поэтому длинную работу можно резать без риска, что она «повиснет». Это ключевое отличие от <code>setTimeout(0)</code>.</li>
    <li>Отдельный приём — уступить поток <strong>перед</strong> тяжёлым рендером после клика: обработать ввод, показать отклик, затем считать. INP измеряет задержку до следующей отрисовки, а не всю работу.</li></ul>`,
    code: `async function process(items) {
  for (const it of items) {
    handle(it);
    if (navigator.scheduling?.isInputPending?.()) await scheduler.yield();
  }
}`,
    tip: 'Объяснение, почему scheduler.yield лучше setTimeout(0) (продолжение имеет повышенный приоритет), — сильная деталь.' },

  { id: 'wx10',
    q: 'Как вы профилируете производительность в Performance-панели?',
    a: `<p>Порядок: записать трейс на <strong>throttled</strong> CPU (4–6x) и медленной сети, иначе на рабочей машине проблем не видно. Дальше смотреть по слоям.</p>
    <ul><li><strong>Дорожка Timings/Metrics</strong> — отметки FCP, LCP, DCL, Load и разметка из <code>performance.mark/measure</code>. Собственные marks вокруг бизнес-этапов — самое полезное, что можно добавить в код.</li>
    <li><strong>Main</strong> — flame chart. Красный уголок и заштрихованная зона обозначают long task; ширина = время. Bottom-Up показывает суммарное self time (кто реально жжёт CPU), Call Tree — иерархию, Event Log — порядок.</li>
    <li><strong>Interactions</strong> — новая дорожка с реальными взаимодействиями и их разбивкой на input delay, processing и presentation delay: сразу видно, что именно ухудшает INP.</li>
    <li>Признаки проблем: фиолетовые полосы Layout/Recalculate Style (forced reflow помечается предупреждением), длинные жёлтые блоки Evaluate Script, частый GC, «Non-composited animation» в Insights.</li>
    <li>Layout shift на дорожке Experience кликается и показывает, какой элемент сдвинулся.</li>
    <li>Полезные соседи: вкладка Performance Insights/Live metrics, Coverage (сколько CSS/JS не использовано), Rendering с paint flashing и layer borders.</li></ul>`,
    tip: 'Скажите про throttling и про собственные performance.mark — без них профилирование обычно бесполезно.' },

  { id: 'wx11',
    q: 'Как искать утечки памяти во фронтенде?',
    a: `<p>Симптомы: рост потребления при повторении сценария, деградация после долгой сессии, падения на мобильных. Методика — <strong>три снапшота</strong>: снять heap snapshot, выполнить сценарий N раз, вернуться в исходное состояние, снять снова, сравнить в режиме Comparison; объекты, которые не исчезли, — кандидаты.</p>
    <ul><li>Ещё точнее — Allocation instrumentation on timeline: синие полосы, оставшиеся синими, это выжившие аллокации.</li>
    <li>Смотреть надо на <strong>retained size</strong> и на цепочку retainers — она показывает, кто держит ссылку.</li>
    <li>Типичные причины в SPA: не снятые слушатели и <code>ResizeObserver</code>/<code>IntersectionObserver</code>; таймеры и интервалы без clear; замыкания на DOM-узлы (detached nodes — фильтр «Detached» в снапшоте); глобальные кеши и Map без ограничения; подписки на store; не отменённые fetch/AbortController; ссылки на компоненты в модульных переменных при HMR.</li>
    <li>Инструменты: <code>performance.measureUserAgentSpecificMemory()</code> для агрегированного мониторинга в проде, вкладка Memory в Task Manager Chrome, а также <code>WeakRef</code>/<code>WeakMap</code> как средство проектирования, а не лечения.</li>
    <li>Важно: снапшот сам вызывает GC, поэтому «рост между снимками» уже очищен от мусора — если объекты остались, ссылка действительно есть.</li></ul>`,
    tip: 'Приём «три снапшота» и фильтр Detached — конкретная методика, которая сразу выделяет ответ.' },

  { id: 'wx12',
    q: 'Что такое TTFB, из чего он складывается и как его улучшать?',
    a: `<p>TTFB — время от начала навигации до первого байта ответа документа. Это не Core Web Vital, но он <strong>нижняя граница</strong> для FCP и LCP: если TTFB 1.5 с, LCP меньше уже не будет. Хороший ориентир — до 0.8 с.</p>
    <p>Складывается из: редиректов, DNS, TCP, TLS, времени ожидания сервера (генерация ответа) и первых байтов. Разложить можно через Navigation Timing (<code>responseStart - startTime</code>) и колонку Timing в DevTools.</p>
    <ul><li><strong>Редиректы</strong> — самая недооценённая часть: цепочка http → https → www легко добавляет сотни миллисекунд; убирается на уровне DNS/CDN и HSTS preload.</li>
    <li><strong>Серверная генерация</strong> — кеширование на CDN (edge cache для HTML, а не только для статики), <code>stale-while-revalidate</code>, оптимизация БД, отказ от блокирующих вызовов при SSR.</li>
    <li><strong>Сеть</strong> — CDN ближе к пользователю, HTTP/2 или HTTP/3, TLS 1.3 и 0-RTT, ранняя отправка через <code>103 Early Hints</code>.</li>
    <li><strong>Streaming SSR</strong> не уменьшает TTFB как метрику, но позволяет отдать первые байты шапки сразу и начать загрузку критических ресурсов — часто это важнее самого числа.</li></ul>`,
    tip: 'Тезис «TTFB — потолок для LCP» плюс упоминание 103 Early Hints делают ответ конкретным.' },

  { id: 'wx13',
    q: 'Как связаны FCP, LCP, TBT и INP? Что мерить в лабе, а что в поле?',
    a: `<p>Цепочка причин обычно такая: <strong>TTFB</strong> задаёт старт, <strong>FCP</strong> (первый любой контент) зависит от блокирующих CSS/JS и шрифтов, <strong>LCP</strong> — от того, когда отрисован крупнейший элемент (обычно герой-картинка или заголовок), а <strong>TBT</strong> — сумма превышений над 50 мс у всех long tasks между FCP и TTI.</p>
    <ul><li>TBT — <strong>лабораторный прокси</strong> для INP: он показывает, насколько занят main thread, но не измеряет реальные взаимодействия. Корреляция есть, совпадения нет: страница может иметь низкий TBT и плохой INP, если тяжёлый обработчик срабатывает только на конкретном клике.</li>
    <li>INP измеряется в поле: берётся почти худшее взаимодействие за визит (примерно 98-й перцентиль) и раскладывается на input delay, processing time, presentation delay.</li>
    <li>Пороги: LCP ≤ 2.5 с, INP ≤ 200 мс, CLS ≤ 0.1 — по 75-му перцентилю реальных пользователей.</li>
    <li>Практика: Lighthouse и трейсы — для поиска <strong>причин</strong>; CrUX и собственный RUM — для оценки <strong>эффекта</strong>. Улучшение лабораторного балла без движения полевых данных не считается результатом.</li>
    <li>Полезные диагностические метрики, которых нет в CWV: FID устарел, зато есть Long Animation Frames (LoAF) API — он показывает, какой скрипт и какая функция вызвали затянутый кадр.</li></ul>`,
    tip: 'Упоминание LoAF API как замены Long Tasks для диагностики INP — свежая и очень предметная деталь.' },

  { id: 'wx14',
    q: 'RUM или синтетика: что и когда использовать?',
    a: `<p>Это дополняющие инструменты, а не альтернативы.</p>
    <p><strong>Синтетика</strong> (Lighthouse, WebPageTest, CI-прогоны) — управляемая среда, воспроизводимость, доступна до релиза, даёт трейсы и водопады, ловит регрессии на PR. Минусы: одна конфигурация устройства и сети, нет реальных пользователей, нет INP как такового (только TBT), не видит редких сценариев и региональной специфики.</p>
    <p><strong>RUM</strong> (web-vitals + свой сборщик, CrUX, коммерческие) — правда о реальных пользователях: распределение по устройствам, странам, типам подключения, маршрутам. Именно RUM отвечает на вопрос «стало ли лучше». Минусы: шум, нужен объём трафика, требует согласия на сбор, сложнее найти причину без атрибуции.</p>
    <ul><li>Правильный процесс: RUM определяет <strong>приоритет</strong> (какая страница и какая метрика хуже всего у 75-го перцентиля), синтетика — <strong>причину</strong>, а RUM снова — <strong>подтверждение</strong> эффекта после релиза.</li>
    <li>Смотреть надо перцентили (p75, p95), а не среднее: среднее скрывает хвост, а именно хвост — это боль пользователей.</li>
    <li>Важно сегментировать по устройству и стране, иначе смена состава аудитории будет выглядеть как регресс.</li>
    <li>Библиотека <code>web-vitals</code> отдаёт атрибуцию (какой элемент LCP, какой обработчик дал INP) — это закрывает главный минус RUM.</li></ul>`,
    tip: 'Формула «RUM — что чинить, синтетика — почему, RUM — помогло ли» — компактный и убедительный ответ.' },

  { id: 'wx15',
    q: 'Как встроить бюджеты производительности в CI?',
    a: `<p>Бюджет — числовой порог, нарушение которого блокирует мердж или как минимум даёт видимый комментарий в PR. Три уровня бюджетов:</p>
    <ul><li><strong>Размер</strong>: вес JS/CSS на маршрут после gzip/brotli. Инструменты — <code>size-limit</code>, <code>bundlesize</code>, встроенные лимиты Rollup/webpack. Самый дешёвый и стабильный вид бюджета.</li>
    <li><strong>Метрики</strong>: Lighthouse CI с <code>assertions</code> на LCP, TBT, CLS. Требует прогонов на стабильном раннере (лучше несколько прогонов и медиана, иначе шум даёт ложные срабатывания).</li>
    <li><strong>Правила</strong>: количество запросов, наличие third-party-скриптов, максимальный размер изображения.</li></ul>
    <p>Организационная часть важнее технической:</p>
    <ul><li>У бюджета должен быть <strong>владелец</strong> и понятная процедура исключения (временное повышение лимита с задачей на возврат), иначе команда начнёт отключать проверку.</li>
    <li>Порог берут от текущего значения плюс небольшой запас, а не от идеала — иначе он красный всегда и его игнорируют.</li>
    <li>Комментарий бота в PR с дельтой по чанкам работает лучше жёсткого блока: видно, что именно выросло.</li>
    <li>Дополнительно полезно следить за полевыми данными и заводить алерт на регресс p75, потому что не всё ловится в CI (например, эксперимент или новый тег в GTM).</li></ul>`,
    tip: 'Мысль «бюджет без владельца и процедуры исключения быстро отключают» — управленческая зрелость, её ценят.' },

  { id: 'wx16',
    q: 'Какие форматы изображений выбирать и по каким критериям?',
    a: `<p>Ориентир 2025 года: <strong>AVIF</strong> — лучшее сжатие (на 20–50% меньше WebP при сопоставимом качестве), поддержка во всех современных браузерах; медленнее кодируется, хуже для мелких изображений и иногда «замыливает» детали на низком качестве. <strong>WebP</strong> — надёжный универсальный вариант, быстрый в кодировании. <strong>JPEG</strong> — фолбэк. <strong>PNG</strong> — только когда нужна безпотерьная прозрачность или пиксель-арт. <strong>SVG</strong> — иконки и иллюстрации, векторно и масштабируемо (но требует санитайзинга при загрузке пользователем — там живут XSS).</p>
    <ul><li>Порядок в <code>&lt;picture&gt;</code> важен: браузер берёт <strong>первый поддерживаемый</strong> source, поэтому AVIF идёт раньше WebP.</li>
    <li>Для анимации — видео (<code>mp4</code>/<code>webm</code>) вместо GIF: экономия в разы; GIF почти всегда ошибка.</li>
    <li>Для LCP-изображения важнее формата бывает <strong>размер в пикселях</strong>: отдача 2000px картинки в контейнер 400px — самая частая реальная проблема.</li>
    <li>Не забывать <code>width</code>/<code>height</code> (CLS), <code>alt</code>, <code>decoding="async"</code> и <code>loading="lazy"</code> для нижних изображений.</li></ul>`,
    code: `<picture>
  <source type="image/avif" srcset="/h.avif">
  <source type="image/webp" srcset="/h.webp">
  <img src="/h.jpg" width="800" height="450" alt="" fetchpriority="high">
</picture>`,
    tip: 'Замечание, что чаще всего проблема не в формате, а в лишних пикселях, — очень практичный акцент.' },

  { id: 'wx17',
    q: 'Как работают srcset и sizes и в чём разница с art direction?',
    a: `<p>Два режима <code>srcset</code>:</p>
    <ul><li><strong>x-дескрипторы</strong> (<code>img.png 1x, img@2x.png 2x</code>) — для изображений фиксированного CSS-размера, выбор по плотности экрана.</li>
    <li><strong>w-дескрипторы</strong> (<code>img-800.jpg 800w</code>) вместе с <code>sizes</code> — для адаптивных. <code>sizes</code> сообщает браузеру, <strong>какую ширину займёт изображение в макете</strong>, и браузер сам умножает на DPR и выбирает кандидата.</li></ul>
    <p>Критический нюанс: браузер выбирает источник в preload scanner, <strong>до применения CSS</strong>, поэтому <code>sizes</code> обязан быть указан вручную и легко расходится с реальным макетом. Неверный <code>sizes</code> — самая частая причина, почему responsive images не дают экономии. Решение — <code>sizes="auto"</code> вместе с <code>loading="lazy"</code> (браузер использует реальный размер) или генерация <code>sizes</code> из тех же токенов, что и CSS.</p>
    <ul><li><strong>Art direction</strong> — это другая задача: не «тот же кадр другого размера», а <strong>другое кадрирование</strong> для узкого экрана. Решается через <code>&lt;picture&gt;</code> с <code>media</code>-условиями, где вы явно указываете файл.</li>
    <li>Правило: <code>srcset</code>+<code>sizes</code> — оптимизация трафика, <code>picture</code>+<code>media</code> — дизайнерское решение, <code>picture</code>+<code>type</code> — выбор формата.</li>
    <li>Браузер может выбрать более крупный кандидат, если он уже в кеше — это нормально и не баг.</li></ul>`,
    code: `<img srcset="/i-400.avif 400w, /i-800.avif 800w, /i-1600.avif 1600w"
     sizes="(min-width: 1024px) 640px, 100vw" src="/i-800.avif" alt="">`,
    tip: 'Объясните, что sizes читается до CSS — отсюда все ошибки; и упомяните sizes="auto" как современное решение.' },

  { id: 'wx18',
    q: 'Зачем image CDN и как он сочетается с priority hints и ленивой загрузкой?',
    a: `<p>Image CDN (Cloudinary, imgproxy, Thumbor, встроенные в Next/Nuxt лоадеры) превращает один исходник в бесконечное множество вариантов по URL-параметрам: размер, формат по <code>Accept</code>, качество, кадрирование, DPR. Это снимает необходимость генерировать десятки файлов на сборке и позволяет менять политику качества без редеплоя.</p>
    <ul><li>Плюсы: автоматический AVIF/WebP через content negotiation, edge-кеш, обрезка по фокусной точке, экономия трафика на 40–70%.</li>
    <li>Риски: <strong>cache miss на первый запрос</strong> (трансформация занимает сотни миллисекунд — для LCP-картинки её нужно прогревать), рост числа уникальных URL (взрыв кеша при произвольных параметрах — ограничивайте набор разрешённых значений), стоимость по трансформациям, и дополнительный домен (нужен <code>preconnect</code>).</li>
    <li><strong>Правило LCP</strong>: изображение первого экрана — <code>fetchpriority="high"</code>, <strong>без</strong> <code>loading="lazy"</code> и без <code>decoding="async"</code>-задержек. Lazy на LCP-картинке — одна из самых частых причин плохого LCP.</li>
    <li>Всё, что ниже сгиба: <code>loading="lazy"</code> плюс при желании <code>fetchpriority="low"</code>. Порог срабатывания lazy у Chrome довольно большой, так что «пустых мест» обычно не появляется.</li>
    <li>Плейсхолдеры (LQIP, blurhash) улучшают восприятие, но помните, что inline-base64 увеличивает HTML и может ухудшить TTFB.</li></ul>`,
    tip: 'Пункт «lazy на LCP-картинке — типовая ошибка» практически всегда попадает в точку.' },

  { id: 'wx19',
    q: 'Как оптимизировать шрифты: FOIT, FOUT, font-display, subsetting, size-adjust?',
    a: `<p><strong>FOIT</strong> — невидимый текст, пока грузится шрифт (блокирует FCP и LCP); <strong>FOUT</strong> — сначала системный шрифт, затем подмена (вызывает сдвиг и портит CLS). Управляется <code>font-display</code>: <code>auto</code>, <code>block</code> (FOIT до 3 с), <code>swap</code> (мгновенный FOUT), <code>fallback</code> (100 мс блока, 3 с подмены), <code>optional</code> (100 мс блока, дальше вообще не подменять в этой загрузке).</p>
    <ul><li><code>swap</code> хорош для LCP, но даёт сдвиг; <code>optional</code> — лучший выбор для CLS, ценой того, что первый визит может пройти системным шрифтом.</li>
    <li><strong>Ключ к нулевому сдвигу</strong> — метрически совпадающий fallback: <code>@font-face</code> с <code>src: local(Arial)</code> и подобранными <code>size-adjust</code>, <code>ascent-override</code>, <code>descent-override</code>, <code>line-gap-override</code>. Так текст не «прыгает» при подмене (инструменты: Fontaine, next/font).</li>
    <li><strong>Self-hosting</strong> вместо Google Fonts: сторонний домен даёт лишний DNS+TLS, а кеш между сайтами давно разделён (cache partitioning), так что выгоды от CDN больше нет.</li>
    <li><strong>woff2</strong> обязателен; <strong>subsetting</strong> по <code>unicode-range</code> убирает неиспользуемые алфавиты (для кириллицы это в разы меньше файла); вариативный шрифт заменяет 4–6 начертаний одним файлом, если реально нужны все.</li>
    <li>Критические шрифты — <code>preload</code> с <code>crossorigin</code>, но не больше 1–2: они конкурируют с LCP-картинкой.</li></ul>`,
    code: `@font-face { font-family: 'Inter Fallback'; src: local('Arial');
  size-adjust: 107%; ascent-override: 90% }`,
    tip: 'Аргумент про cache partitioning (общий кеш Google Fonts больше не работает) — свежий и убедительный.' },

  { id: 'wx20',
    q: 'Расскажите про CSP: как она устроена и как её реально внедрить?',
    a: `<p>CSP — заголовок, ограничивающий источники ресурсов и способы выполнения кода. Главная защита — от XSS: даже при инъекции скрипт не выполнится, если не соответствует политике.</p>
    <ul><li>Директивы: <code>default-src</code>, <code>script-src</code>, <code>style-src</code>, <code>img-src</code>, <code>connect-src</code>, <code>font-src</code>, <code>frame-src</code>, <code>frame-ancestors</code>, <code>base-uri</code>, <code>form-action</code>, <code>object-src</code>, <code>report-to</code>.</li>
    <li>Часто забывают три критичных: <code>base-uri 'none'</code> (иначе инъекция <code>&lt;base&gt;</code> перенаправит все относительные скрипты), <code>object-src 'none'</code> и <code>form-action</code> (защита от увода данных формы).</li>
    <li>Allowlist доменов — <strong>слабая</strong> модель: исследование Google показало, что большинство allowlist-политик обходятся через JSONP-эндпоинты и открытые CDN на разрешённых доменах. Рабочая модель — nonce/hash плюс <code>'strict-dynamic'</code>.</li>
    <li>Внедрять надо через <code>Content-Security-Policy-Report-Only</code> с <code>report-to</code>: собрать отчёты, разобрать ложные срабатывания (расширения браузера дают много шума), затем включить в блокирующем режиме.</li>
    <li>CSP не заменяет экранирование: это второй рубеж (defense in depth), а не замена безопасного рендеринга.</li></ul>`,
    code: `Content-Security-Policy: default-src 'self'; script-src 'nonce-r4nd0m' 'strict-dynamic'; object-src 'none'; base-uri 'none'`,
    tip: 'Ссылка на исследование Google про обходимость allowlist через JSONP — сильный и конкретный аргумент.' },

  { id: 'wx21',
    q: 'Nonce, hash или strict-dynamic: что выбрать и почему?',
    a: `<p><strong>Nonce</strong> — случайное значение, генерируемое сервером <strong>на каждый ответ</strong> и проставляемое и в заголовок, и в атрибут <code>nonce</code> каждого доверенного тега. Требует динамического рендеринга: на статике с CDN-кешем nonce нельзя переиспользовать — повторяющийся nonce эквивалентен <code>unsafe-inline</code>.</p>
    <p><strong>Hash</strong> (<code>'sha256-...'</code>) — контрольная сумма содержимого инлайн-скрипта. Подходит для статических страниц и для CDN-кеша, но требует пересчёта при каждом изменении кода и плохо работает с динамическими скриптами.</p>
    <p><strong>strict-dynamic</strong> — снимает ограничение по URL для скриптов, загруженных <strong>программно</strong> доверенным скриптом, и одновременно <strong>отключает</strong> все allowlist-домены и <code>'self'</code>. Это решает проблему бандлеров и аналитики, которые подгружают чанки динамически, и делает политику независимой от списка доменов.</p>
    <ul><li>Рекомендуемая связка: nonce + <code>'strict-dynamic'</code> + фолбэки <code>https:</code> и <code>'unsafe-inline'</code> в конце — старые браузеры прочитают их, новые проигнорируют, так политика работает везде.</li>
    <li>Nonce должен быть криптографически случайным (минимум 128 бит), уникальным на ответ, и его нельзя логировать или отдавать в кешируемом HTML.</li>
    <li>Важно: nonce на <code>&lt;script&gt;</code> не защищает от инъекции <strong>внутрь</strong> уже доверенного скрипта — от этого спасают Trusted Types.</li></ul>`,
    tip: 'Ключевая фраза: strict-dynamic отключает allowlist — это и есть его смысл, а не просто «разрешить больше».' },

  { id: 'wx22',
    q: 'Что такое Trusted Types и какую проблему они решают?',
    a: `<p>CSP не спасает от DOM XSS: сам ваш скрипт может записать пользовательскую строку в <code>innerHTML</code>, и браузер выполнит её как разметку. Trusted Types (<code>require-trusted-types-for 'script'</code>) переводят <strong>все опасные sink</strong> (<code>innerHTML</code>, <code>outerHTML</code>, <code>document.write</code>, <code>eval</code>, <code>src</code> у script, <code>setAttribute</code> на опасных атрибутах) в режим, где они принимают <strong>только</strong> специальные объекты <code>TrustedHTML</code>/<code>TrustedScript</code>/<code>TrustedScriptURL</code>, а не строки.</p>
    <ul><li>Создать такой объект можно только через политику, зарегистрированную явно (<code>trustedTypes.createPolicy</code>), а список разрешённых имён политик задаётся директивой <code>trusted-types</code>. Тем самым весь небезопасный код собирается в одном аудируемом месте.</li>
    <li>На практике политика делегирует санитайзинг в DOMPurify — то есть Trusted Types не чистят HTML, они <strong>гарантируют, что чистка не была пропущена</strong>.</li>
    <li>Внедрение: сначала report-only, сбор нарушений, правка библиотек (многие старые UI-киты пишут в innerHTML), затем enforce. Внутри Google это дало кратное падение числа DOM XSS.</li>
    <li>Поддержка: Chromium давно, Firefox и Safari подтянулись позже; в неподдерживающих браузерах это просто no-op, поэтому внедрение безопасно.</li>
    <li>Дополнение — нативный <code>setHTML()</code>/Sanitizer API, который убирает потребность в сторонней библиотеке.</li></ul>`,
    code: `trustedTypes.createPolicy('default', {
  createHTML: (s) => DOMPurify.sanitize(s)
});`,
    tip: 'Формулировка «Trusted Types не чистят HTML, а гарантируют, что чистка вызвана» точно передаёт суть.' },

  { id: 'wx23',
    q: 'Что делает HSTS и в чём риск preload-списка?',
    a: `<p><code>Strict-Transport-Security</code> говорит браузеру ходить на домен <strong>только</strong> по HTTPS в течение <code>max-age</code>, даже если пользователь ввёл http:// или кликнул по http-ссылке. Это закрывает SSL-stripping — атаку, при которой первый незашифрованный запрос перехватывается.</p>
    <ul><li>Остаётся дыра «первого визита»: до первого HTTPS-ответа браузер про политику не знает. Её закрывает <strong>preload-список</strong>, вшитый в браузеры (hstspreload.org), требующий <code>max-age</code> минимум год, <code>includeSubDomains</code> и <code>preload</code>.</li>
    <li><strong>Риск</strong>: попадание в preload-список практически необратимо — удаление занимает месяцы и доезжает до пользователей только с новой версией браузера. Если какой-то поддомен (внутренний сервис, dev-стенд, IoT-устройство, почтовый шлюз) не умеет HTTPS, он станет недоступен для всех сотрудников и пользователей.</li>
    <li>Правильная последовательность: короткий <code>max-age</code> → проверить все поддомены → увеличить до года → добавить <code>includeSubDomains</code> → только затем <code>preload</code>.</li>
    <li>HSTS не защищает от скомпрометированного сертификата — для этого нужны CAA-записи и мониторинг Certificate Transparency (HPKP признан вредным и удалён).</li></ul>`,
    code: `Strict-Transport-Security: max-age=63072000; includeSubDomains; preload`,
    tip: 'Необратимость preload-списка и риск сломать внутренние поддомены — это то, что должен знать senior.' },

  { id: 'wx24',
    q: 'Что такое clickjacking и как от него защищаться?',
    a: `<p>Атакующий встраивает ваш сайт в прозрачный <code>iframe</code> поверх своей приманки, и пользователь, думая, что кликает по кнопке атакующего, нажимает на кнопку в вашем интерфейсе (перевод денег, выдача прав, подтверждение). Разновидности: likejacking, cursorjacking, drag-and-drop-атаки для увода данных.</p>
    <p>Защита по слоям:</p>
    <ul><li><strong>CSP <code>frame-ancestors 'none'</code></strong> (или явный список) — современный и предпочтительный способ: он поддерживает несколько источников, работает по всей цепочке вложенных фреймов и не имеет проблем <code>ALLOW-FROM</code>.</li>
    <li><strong><code>X-Frame-Options: DENY|SAMEORIGIN</code></strong> — легаси-заголовок для старых браузеров; поддерживается всеми, но <code>ALLOW-FROM</code> не работает в Chrome. Держат оба заголовка; при конфликте современные браузеры отдают приоритет <code>frame-ancestors</code>.</li>
    <li><strong>SameSite-cookie</strong> (<code>Lax</code>/<code>Strict</code>) — второй рубеж: даже во фрейме запрос не пойдёт с сессионной кукой, и действие не выполнится от имени пользователя.</li>
    <li>Для критичных операций — повторное подтверждение и защита от «слепого» клика (например, требование ввести сумму или код).</li>
    <li>JS frame-busting (<code>if (top !== self)</code>) устарел и обходится через <code>sandbox</code>.</li></ul>`,
    code: `Content-Security-Policy: frame-ancestors 'self' https://partner.ru
X-Frame-Options: SAMEORIGIN`,
    tip: 'Скажите, что frame-ancestors переопределяет X-Frame-Options и что оба всё ещё ставят вместе.' },

  { id: 'wx25',
    q: 'Что делают Referrer-Policy и Permissions-Policy?',
    a: `<p><strong>Referrer-Policy</strong> управляет заголовком <code>Referer</code>. Утечка здесь реальна: полный URL с токеном сброса пароля, id заказа или поисковым запросом уходит на любой сторонний домен, куда ведёт ссылка или откуда грузится картинка.</p>
    <ul><li>Значения по возрастанию строгости: <code>unsafe-url</code>, <code>no-referrer-when-downgrade</code>, <code>strict-origin-when-cross-origin</code> (значение по умолчанию в современных браузерах: полный URL на своём origin, только origin наружу, ничего при downgrade на http), <code>same-origin</code>, <code>strict-origin</code>, <code>no-referrer</code>.</li>
    <li>Настраивается заголовком, мета-тегом или атрибутом <code>referrerpolicy</code> на конкретной ссылке/картинке. Полностью убирать реферер не всегда правильно — часть партнёрских и аналитических интеграций на нём держится.</li></ul>
    <p><strong>Permissions-Policy</strong> (бывший Feature-Policy) выключает браузерные возможности для документа и его фреймов: камера, микрофон, геолокация, платежи, датчики, autoplay, а также <code>interest-cohort</code>.</p>
    <ul><li>Практический смысл — <strong>ограничение стороннего кода</strong>: даже скомпрометированный виджет или встроенная реклама не сможет запросить камеру или геолокацию, если возможность отключена на уровне документа.</li>
    <li>Синтаксис: <code>camera=(), geolocation=(self), payment=(self "https://pay.ru")</code>. Атрибут <code>allow</code> на <code>iframe</code> делегирует разрешение вниз, но никогда не расширяет то, что запрещено сверху.</li>
    <li>Дополнительно позволяет включать «reporting» и отслеживать нарушения через Reporting API.</li></ul>`,
    code: `Referrer-Policy: strict-origin-when-cross-origin
Permissions-Policy: camera=(), microphone=(), geolocation=(self)`,
    tip: 'Пример с токеном сброса пароля в URL, утекающим через Referer, — самая наглядная мотивация.' },

  { id: 'wx26',
    q: 'Что именно закрывает Same-Origin Policy и чего она не закрывает?',
    a: `<p>Origin = схема + хост + порт. SOP запрещает документу <strong>читать</strong> данные другого origin: DOM чужого фрейма, тело ответа, содержимое canvas, «испорченного» чужой картинкой, куки и storage.</p>
    <p>Чего SOP <strong>не</strong> запрещает — и это главная часть ответа:</p>
    <ul><li><strong>Отправку</strong> запросов: форма, <code>&lt;img&gt;</code>, <code>&lt;script&gt;</code>, <code>fetch</code> с <code>no-cors</code> уходят на чужой origin вместе с куками. Ответ вы не прочитаете, но <strong>побочный эффект на сервере уже произошёл</strong> — это и есть CSRF.</li>
    <li>Встраивание ресурсов: картинки, скрипты, стили, фреймы, шрифты грузятся кросс-доменно по умолчанию.</li>
    <li>Навигацию и <code>window.open</code>; ограниченное межоконное взаимодействие (<code>postMessage</code>, <code>window.length</code>, <code>location</code> на запись).</li>
    <li>Утечки по побочным каналам: время загрузки, размер, наличие ошибки — на этом строятся XS-Leaks.</li></ul>
    <p>Механизмы, ослабляющие или усиливающие SOP: CORS (контролируемое разрешение чтения), <code>document.domain</code> (устарел и отключается), CORP/COEP/COOP (защита от Spectre и включение <code>SharedArrayBuffer</code>), <code>crossorigin</code>-атрибут, Fetch Metadata (<code>Sec-Fetch-Site</code>) для серверной проверки происхождения запроса.</p>`,
    tip: 'Акцент «SOP запрещает читать, но не запрещает отправлять» — прямой мост к объяснению CSRF.' },

  { id: 'wx27',
    q: 'Разберите SameSite-cookie подробно. Что изменилось и где ловушки?',
    a: `<p><code>SameSite</code> определяет, отправлять ли куку в кросс-сайтовом запросе. Значения:</p>
    <ul><li><strong>Strict</strong> — только при запросах с того же сайта. Максимальная защита, но при переходе по ссылке извне пользователь увидит себя неавторизованным (частая жалоба «зашёл из поиска и меня разлогинило»).</li>
    <li><strong>Lax</strong> — отправляется при <strong>навигации верхнего уровня методом GET</strong>. Это значение по умолчанию в современных браузерах. Закрывает классический CSRF на POST, но не защищает от «CSRF через GET», если у вас есть изменяющие состояние GET-эндпоинты.</li>
    <li><strong>None</strong> — отправляется всегда, но <strong>обязателен</strong> <code>Secure</code>; иначе кука отбрасывается. Нужен для встраиваемых виджетов, SSO и кросс-доменных API.</li></ul>
    <p>Ловушки и детали:</p>
    <ul><li>«Site» — это eTLD+1, а не origin: <code>a.site.ru</code> и <code>b.site.ru</code> — один сайт, поэтому SameSite не изолирует поддомены. Для этого есть префикс <code>__Host-</code> (требует Secure, без Domain, path=/).</li>
    <li>Chrome применял двухминутную «Lax + POST» поблажку для свежих кук — на неё нельзя полагаться.</li>
    <li>SameSite — <strong>не замена</strong> CSRF-токенам: он не помогает при XSS, при поддомене под контролем атакующего и при браузерах без поддержки. Актуальная схема — SameSite=Lax плюс токен (double submit или синхронизатор) или проверка <code>Sec-Fetch-Site</code>/Origin на сервере.</li>
    <li>Отдельно идёт третья сторона: сторонние куки в Chrome и так ограничиваются, и виджетам нужен CHIPS (<code>Partitioned</code>) или Storage Access API.</li></ul>`,
    code: `Set-Cookie: sid=...; HttpOnly; Secure; SameSite=Lax; Path=/`,
    tip: 'Уточнение, что site = eTLD+1 и поддомены не изолированы, — деталь, отличающая понимание от заучивания.' },

  { id: 'wx28',
    q: 'Что такое prototype pollution и как она эксплуатируется во фронтенде?',
    a: `<p>Атака на JS-рантайм: если код рекурсивно копирует пользовательские данные в объект (deep merge, <code>extend</code>, парсинг query-строки, десериализация) и не фильтрует ключ <code>__proto__</code> (а также <code>constructor.prototype</code>), атакующий записывает свойство в <code>Object.prototype</code>. После этого <strong>все</strong> объекты в приложении получают это свойство.</p>
    <ul><li>Эксплуатация на клиенте: подмена значений, которые код проверяет по умолчанию — <code>if (!options.sanitize)</code>, флаги фич, <code>innerHTML</code>-шаблоны. Классика — превращение в DOM XSS через загрязнение опций санитайзера или шаблонизатора. Векторы часто идут прямо из URL: <code>?__proto__[onerror]=alert(1)</code>.</li>
    <li>Исторические CVE: lodash <code>merge</code>, jQuery <code>extend</code>, minimist, querystring-парсеры.</li>
    <li>Защита в коде: <code>Object.create(null)</code> для словарей, <code>Map</code> вместо объекта, отбрасывание ключей <code>__proto__</code>/<code>constructor</code>/<code>prototype</code> при мердже, <code>Object.hasOwn</code> вместо <code>in</code>, схема-валидация входных данных, <code>Object.freeze(Object.prototype)</code> как радикальная мера.</li>
    <li>Отдельно: <code>JSON.parse</code> сам по себе безопасен (не создаёт прототип), опасен именно последующий merge.</li>
    <li>Родственная тема на сервере — prototype pollution в Node приводит к RCE через gadget-цепочки, поэтому это не «безобидный фронтовый баг».</li></ul>`,
    code: `const safe = Object.create(null);
if (key === '__proto__' || key === 'constructor') continue;`,
    tip: 'Пример вектора через query-строку и последующий DOM XSS показывает, что вы понимаете цепочку эксплуатации.' },

  { id: 'wx29',
    q: 'Как вы защищаете фронтенд от supply chain атак в npm?',
    a: `<p>Угроза реальна: typosquatting, компрометация мейнтейнера, вредоносный <code>postinstall</code>, «протестированный» пакет, который через полгода получает вредоносное обновление (event-stream, ua-parser-js, colors, а в 2024–2025 — серия атак через угнанные токены публикации).</p>
    <p>Слои защиты:</p>
    <ul><li><strong>Lockfile обязателен и коммитится</strong>; в CI только <code>npm ci</code>/<code>pnpm install --frozen-lockfile</code>. Ревью изменений lockfile в PR — недооценённая практика.</li>
    <li><code>--ignore-scripts</code> по умолчанию (pnpm умеет <code>onlyBuiltDependencies</code>) — большинство атак срабатывает именно в install-скриптах.</li>
    <li>Пиннинг версий или хотя бы <strong>задержка обновлений</strong> (не ставить релиз в первые дни), Renovate с группировкой и минимальным возрастом версии.</li>
    <li><code>npm audit</code>/Snyk/Dependabot в CI, генерация SBOM, проверка провенанса (npm provenance, sigstore).</li>
    <li>Минимизация зависимостей: каждая транзитивная библиотека — это доверие чужому мейнтейнеру. Сотня зависимостей означает сотни точек отказа.</li>
    <li>Ограничение прав в CI: токены с минимальными правами, отдельный шаг публикации, 2FA у мейнтейнеров, запрет на исходящую сеть на этапе сборки.</li>
    <li>Для стороннего кода в рантайме — CSP, SRI и вынос виджетов в изолированный iframe.</li></ul>`,
    tip: 'Практика «не обновляться в первые дни после релиза» — простая и очень действенная мера, её редко называют.' },

  { id: 'wx30',
    q: 'Что такое SRI и какие у неё ограничения?',
    a: `<p>Subresource Integrity — атрибут <code>integrity</code> с хешем содержимого: браузер загружает ресурс, считает хеш и <strong>отказывается выполнять</strong>, если он не совпал. Это защита от подмены файла на CDN и от MITM в случае скомпрометированного стороннего хостинга.</p>
    <ul><li>Работает на <code>&lt;script&gt;</code> и <code>&lt;link rel="stylesheet"&gt;</code>. Для кросс-доменных ресурсов обязателен атрибут <code>crossorigin="anonymous"</code>, иначе проверка невозможна и ресурс блокируется.</li>
    <li>Можно указать несколько хешей через пробел — подойдёт любой совпавший (удобно при ротации версий).</li>
    <li><strong>Ограничения</strong>: не подходит для ресурсов, которые меняются по замыслу (аналитика, A/B-скрипты, Google Tag Manager, шрифты по content negotiation) — а именно они и есть основной риск. Не защищает от вредоносного кода, загруженного <strong>изнутри</strong> проверенного скрипта. Не покрывает динамический <code>import()</code> напрямую (нужна import map с integrity).</li>
    <li>Появилась поддержка <code>integrity</code> в import maps и обсуждается SRI для модулей — это закрывает часть пробела.</li>
    <li>Для собственных ассетов SRI обычно избыточен, если вы контролируете CDN и используете иммутабельные хешированные имена; ценность именно в стороннем коде.</li></ul>`,
    code: `<script src="https://cdn.x/lib.js" integrity="sha384-..." crossorigin="anonymous"></script>`,
    tip: 'Честное «SRI неприменим к тому, что меняется — то есть к самому опасному стороннему коду» звучит зрело.' },

  { id: 'wx31',
    q: 'Как устроен JWT и в чём его типичные уязвимости?',
    a: `<p>Три base64url-части через точку: header (<code>alg</code>, <code>kid</code>), payload (claims: <code>sub</code>, <code>exp</code>, <code>iat</code>, <code>aud</code>, <code>iss</code>, <code>jti</code>) и подпись. Payload <strong>не шифруется</strong> — это кодирование, а не шифрование: класть туда персональные данные нельзя (для шифрования есть JWE).</p>
    <p>Классические уязвимости:</p>
    <ul><li><strong><code>alg: none</code></strong> — библиотека принимает токен без подписи. Всегда указывайте ожидаемый алгоритм явно, а не берите его из header.</li>
    <li><strong>Путаница алгоритмов</strong>: токен, подписанный HS256 публичным RSA-ключом, проверяется как валидный, если код доверяет header.</li>
    <li>Слабый секрет для HS256 — брутфорсится офлайн.</li>
    <li><code>kid</code> с path traversal или SQL-инъекцией; <code>jku</code>/<code>x5u</code>, указывающие на сервер атакующего.</li>
    <li>Непроверенные <code>aud</code>/<code>iss</code> — токен от другого сервиса проходит.</li></ul>
    <p>Главный архитектурный минус: JWT <strong>невозможно отозвать</strong> без состояния на сервере — до истечения <code>exp</code> он валиден. Отсюда короткий TTL access-токена (5–15 минут) и отдельный механизм для refresh.</p>`,
    tip: 'Фраза «JWT — это подписанные, а не зашифрованные данные» плюс проблема отзыва закрывают половину вопросов.' },

  { id: 'wx32',
    q: 'Где хранить токены, как делать ротацию refresh и как отзывать доступ?',
    a: `<p><strong>Хранение.</strong> Лучший вариант для веба — refresh-токен в куке <code>HttpOnly; Secure; SameSite=Lax|Strict; Path=/auth/refresh</code>, access-токен в памяти JS (переменная/замыкание). localStorage читается любым XSS; кука с HttpOnly — нет, зато требует защиты от CSRF (SameSite плюс токен или проверка Origin). Полностью cookie-based сессия (opaque session id) остаётся самым простым и безопасным вариантом, если фронт и бэк на одном сайте.</p>
    <p><strong>Ротация.</strong> Каждый вызов refresh выдаёт новый refresh-токен и инвалидирует старый (<code>jti</code> в базе). Если приходит <strong>уже использованный</strong> токен — это признак кражи: сервер аннулирует всё семейство токенов и разлогинивает пользователя. Это стандартная refresh token rotation с reuse detection.</p>
    <ul><li>Нужна защита от гонки: несколько параллельных 401 не должны инициировать несколько refresh — единый promise-мьютекс в интерцепторе и очередь ожидающих запросов.</li>
    <li>Абсолютный срок жизни семейства (например, 30 дней) в дополнение к скользящему.</li></ul>
    <p><strong>Отзыв.</strong> Access-токен короткоживущий, поэтому реальный отзыв — это инвалидация refresh плюс, при необходимости, denylist по <code>jti</code> или <code>tokenVersion</code> в claim, который сверяется с БД (тогда теряется stateless-преимущество — это осознанный размен).</p>`,
    tip: 'Reuse detection и аннулирование семейства токенов — конкретика, по которой видно, что вы это проектировали.' },

  { id: 'wx33',
    q: 'Как работает OAuth2/OIDC с PKCE во фронтенде?',
    a: `<p>OAuth2 — про <strong>авторизацию</strong> (доступ к ресурсу), OIDC — надстройка про <strong>аутентификацию</strong> (кто пользователь), добавляющая <code>id_token</code> и <code>/userinfo</code>. Для SPA и мобильных единственный рекомендованный поток — <strong>Authorization Code + PKCE</strong>; implicit flow объявлен устаревшим, потому что токен попадал в URL и в историю.</p>
    <p>PKCE закрывает перехват кода: клиент генерирует случайный <code>code_verifier</code>, отправляет в authorize его хеш (<code>code_challenge</code>, метод S256), а при обмене кода на токен предъявляет исходный verifier. Перехваченный код без verifier бесполезен.</p>
    <ul><li>Обязательные проверки: <code>state</code> (защита от CSRF на редиректе), <code>nonce</code> (привязка id_token к сессии), валидация подписи и <code>aud</code>/<code>iss</code>/<code>exp</code> id_token, точное совпадение <code>redirect_uri</code>.</li>
    <li>Для SPA всё чаще применяют <strong>BFF-паттерн</strong>: обмен кода и хранение токенов выполняет свой бэкенд, а браузер работает по обычной HttpOnly-сессии. Это официально рекомендуемый подход, потому что убирает токены из досягаемости XSS.</li>
    <li>Silent renew через скрытый iframe сломался из-за блокировки сторонних кук — отсюда либо refresh token rotation в SPA, либо BFF.</li>
    <li>Не путайте: <code>id_token</code> нельзя отправлять как bearer к API, для этого есть <code>access_token</code>.</li></ul>`,
    tip: 'Упоминание BFF как современной рекомендации вместо хранения токенов в SPA — сильный архитектурный ответ.' },

  { id: 'wx34',
    q: 'Чем отличается аутентификация в SPA и в SSR-приложении?',
    a: `<p><strong>SPA.</strong> Браузер получает статический бандл, затем сам запрашивает данные. Токен нужен клиентскому коду, поэтому либо он в памяти (теряется при перезагрузке — нужен silent refresh), либо в куке. Проблемы: вспышка неаутентифицированного состояния при загрузке, защита маршрутов только на клиенте (её всегда надо дублировать на API), сложность с SEO и с предзагрузкой персональных данных.</p>
    <p><strong>SSR.</strong> Сервер рендерит с уже известной сессией: первый HTML сразу персонализирован, нет вспышки, редирект неавторизованного делается на сервере (быстрее и надёжнее). Здесь естественна HttpOnly-кука, и токен вообще не попадает в JS.</p>
    <p>Что важно проговорить:</p>
    <ul><li>SSR-фреймворки требуют аккуратности с <strong>кешированием</strong>: персонализированный HTML нельзя класть в общий CDN-кеш (<code>Cache-Control: private, no-store</code> и <code>Vary: Cookie</code>) — иначе один пользователь увидит данные другого. Это самая опасная ошибка в этой теме.</li>
    <li>При гидратации персональные данные попадают в <code>__NEXT_DATA__</code>-подобный инлайн — их надо фильтровать, иначе секреты уезжают в HTML.</li>
    <li>В Next.js App Router проверка должна быть в самом Server Component или в data layer, а не только в middleware (обход через прямой запрос к RSC-эндпоинту — реальный класс уязвимостей).</li>
    <li>Гибрид: SSR/BFF владеет сессией, а клиент ходит на свой же origin — тогда CSRF решается SameSite, а CORS не нужен вовсе.</li></ul>`,
    tip: 'Риск закешировать персонализированный SSR-ответ на CDN — тот пример, который сразу показывает продовый опыт.' },

  { id: 'wx35',
    q: 'Что означают тайминги в Network waterfall DevTools?',
    a: `<p>Разбивка запроса: <strong>Queueing</strong> (очередь: лимит соединений, приоритет ниже, ожидание диска), <strong>Stalled</strong> (ожидание сокета/прокси), <strong>DNS Lookup</strong>, <strong>Initial connection</strong> (TCP-хендшейк), <strong>SSL</strong>, <strong>Request sent</strong>, <strong>Waiting (TTFB)</strong> — сервер думает, <strong>Content Download</strong> — скачивание тела.</p>
    <p>Как читать:</p>
    <ul><li>Длинный <strong>Waiting</strong> — проблема на сервере или в сети до сервера, фронтенд её не починит кроме кеша и CDN.</li>
    <li>Длинный <strong>Content Download</strong> — ресурс большой или полоса узкая: сжатие, формат, разбивка.</li>
    <li>Длинный <strong>Queueing/Stalled</strong> в HTTP/1.1 — упёрлись в 6 соединений на хост; в HTTP/2 — низкий приоритет или конкуренция.</li>
    <li><strong>Ступенчатый водопад</strong> (каждый запрос начинается после предыдущего) — цепочка зависимостей: HTML → JS → fetch → картинка. Это главный признак того, что нужен preload или изменение архитектуры загрузки.</li></ul>
    <p>Дополнительно: строка <code>(from disk cache)</code>/<code>(from memory cache)</code>/<code>(from prefetch cache)</code>, колонки Priority, Protocol (h2/h3), Initiator (кто запросил — кликабельная цепочка), «Blocked requests», а также фильтр <code>larger-than:</code>. Полезно включить «Big request rows» и снимать трейс с throttling — без него водопад не отражает реальность.</p>`,
    tip: 'Умение назвать ступенчатый водопад как признак цепочки зависимостей — это то, что реально спрашивают.' },

  { id: 'wx36',
    q: 'Как отлаживать фронтенд на реальных мобильных устройствах?',
    a: `<p>Эмулятор в DevTools меняет размер и user agent, но не воспроизводит реальный CPU, память, GPU, сеть и особенности мобильных браузеров. Поэтому на реальных устройствах:</p>
    <ul><li><strong>Android</strong>: USB-отладка плюс <code>chrome://inspect</code> — полноценные DevTools для устройства, включая профилирование и port forwarding на локальный дев-сервер.</li>
    <li><strong>iOS</strong>: Safari Web Inspector через «Develop → устройство» (нужно включить Web Inspector в настройках Safari на телефоне). Для WebView в приложениях — тот же путь.</li>
    <li>Когда провода нет: <strong>Eruda</strong> или <strong>vConsole</strong> — консоль прямо на странице; <strong>Charles/Proxyman</strong> для перехвата трафика; удалённые фермы (BrowserStack) для матрицы устройств.</li>
    <li>HTTPS для dev-сервера обязателен, если тестируете SW, геолокацию, камеру.</li></ul>
    <p>Что ломается именно на мобильных: тепловой троттлинг (после минуты нагрузки производительность падает вдвое), ограничение памяти и выгрузка вкладок (bfcache и <code>pagehide</code> вместо <code>unload</code>), <code>100vh</code> и панели браузера, задержки тач-событий и <code>touch-action</code>, отсутствие hover, клавиатура, перекрывающая поля, ограничения на автоплей и на background-таймеры, специфика Safari (запрет ряда API, агрессивная очистка storage через 7 дней).</p>`,
    tip: 'Тепловой троттлинг и выгрузка вкладок — то, чего не увидишь в эмуляторе, и это ценный практический акцент.' },

  { id: 'wx37',
    q: 'Как вообще работает бандлинг и что реально уменьшает размер?',
    a: `<p>Сборщик строит <strong>граф модулей</strong> от точек входа, разрешает импорты, применяет трансформации (TS, JSX), выполняет tree shaking, разбивает на чанки и генерирует рантайм-загрузчик с картой чанков.</p>
    <ul><li><strong>Tree shaking</strong> работает только на статических ESM-импортах: <code>require</code>, динамические ключи и реэкспорт «звёздочкой» ломают анализ. Ключевой ограничитель — <strong>side effects</strong>: без <code>"sideEffects": false</code> в package.json бандлер обязан сохранить модуль целиком, даже если экспорты не используются.</li>
    <li><strong>Code splitting</strong>: точки входа, динамический <code>import()</code> (по маршрутам и по тяжёлым компонентам вроде редактора и графиков), выделение общих чанков. Чрезмерная дробность вредна: много мелких запросов и водопад зависимостей.</li>
    <li><strong>Scope hoisting</strong> объединяет модули в одну область видимости — меньше обёрток и лучше минификация.</li>
    <li>Реальные победы обычно не в настройках, а в решениях: заменить moment на date-fns/Temporal, не тащить всю lodash, вынести полифиллы под <code>module/nomodule</code>, убрать дублирующиеся версии библиотеки (<code>dedupe</code>), не бандлить локали целиком.</li>
    <li>Диагностика — visualizer/bundle-analyzer по <strong>сжатому</strong> размеру и вкладка Coverage для неиспользуемого кода.</li></ul>`,
    code: `const Editor = lazy(() => import('./Editor'));`,
    tip: 'Поле sideEffects как условие работы tree shaking — конкретика, которую знают далеко не все.' },

  { id: 'wx38',
    q: 'Чем отличаются esbuild, Rollup, Vite, webpack и Turbopack?',
    a: `<p><strong>esbuild</strong> (Go) — предельно быстрый транспайлер/бандлер; жертвует продвинутым tree shaking и экосистемой плагинов. Идеален для трансформации и для dev-зависимостей.</p>
    <p><strong>Rollup</strong> (JS) — эталон для библиотек: лучший tree shaking, чистый ESM на выходе, богатая плагинная модель.</p>
    <p><strong>Vite</strong> — не бандлер, а dev-сервер плюс сборка: в разработке отдаёт нативные ESM без бандлинга (мгновенный старт независимо от размера проекта), зависимости пребандлит esbuild-ом, прод собирает Rollup-ом. Расхождение dev и prod пайплайнов — его главный исторический недостаток; в новых версиях его снимает <strong>Rolldown</strong> (Rust-порт Rollup), унифицирующий оба режима.</p>
    <p><strong>webpack</strong> — самый зрелый и гибкий, огромная экосистема, Module Federation для микрофронтендов; медленный и сложный в конфигурации. Rspack — совместимый Rust-порт для тех, кто не хочет переписывать конфиг.</p>
    <p><strong>Turbopack</strong> (Rust, Vercel) — инкрементальный сборщик для Next.js с функционально-кешируемым графом задач: пересборка пересчитывает только затронутое. Вне Next пока применяется мало.</p>
    <ul><li>Общий тренд: тяжёлая работа уезжает в Rust/Go, а конкуренция идёт за скорость инкрементальной пересборки, а не холодной сборки.</li>
    <li>Практический выбор: приложение — Vite или Next; библиотека — Rollup/tsup; легаси с Module Federation — webpack/Rspack.</li></ul>`,
    tip: 'Понимание, что Vite — это два разных пайплайна и что Rolldown их объединяет, показывает актуальность знаний.' },

  { id: 'wx39',
    q: 'Как устроен HMR и почему он иногда не работает?',
    a: `<p>Dev-сервер держит WebSocket с клиентом. При изменении файла сервер определяет, какие модули затронуты, и отправляет обновление; клиентский рантайм подменяет модуль в кеше и вызывает зарегистрированные обработчики принятия (<code>import.meta.hot.accept</code> в Vite, <code>module.hot.accept</code> в webpack).</p>
    <ul><li>Ключевое понятие — <strong>граница принятия</strong>. Если модуль не умеет принимать обновление, оно «всплывает» вверх по графу импортов до ближайшего модуля, который умеет; если такого нет — полная перезагрузка страницы.</li>
    <li>React Fast Refresh умеет сохранять состояние компонента, но только при соблюдении правил: компонент должен быть <strong>именованным экспортом верхнего уровня</strong>, файл не должен экспортировать одновременно компоненты и не-компоненты (иначе граница ломается), анонимные стрелочные экспорты и HOC-обёртки часто сбивают идентификацию.</li>
    <li>Состояние вне React (модульные переменные, синглтоны, подписки) при HMR не сбрасывается — отсюда «утечки» и дублирующиеся слушатели в dev. Их надо чистить в <code>import.meta.hot.dispose</code>.</li>
    <li>Типовые причины поломки: изменения в файлах вне графа (конфиги, переменные окружения), CSS-in-JS с рантаймом, циклические импорты, отсутствие watch на сетевых/докерных файловых системах (нужен polling), прокси и HTTPS, ломающие WebSocket.</li></ul>`,
    code: `if (import.meta.hot) import.meta.hot.dispose(() => socket.close());`,
    tip: 'Правило «файл экспортирует только компоненты, иначе Fast Refresh ломается» — то, с чем сталкиваются ежедневно.' },

  { id: 'wx40',
    q: 'Как работают source maps и как безопасно использовать их в проде?',
    a: `<p>Source map — JSON с полем <code>mappings</code> в кодировке VLQ base64: он сопоставляет позиции в собранном файле позициям в исходниках, плюс <code>sources</code>, <code>names</code> и опционально <code>sourcesContent</code> (сами исходники внутри карты). Подключается комментарием <code>sourceMappingURL</code> или заголовком <code>SourceMap</code>.</p>
    <ul><li>Типы в webpack/Vite различаются компромиссом скорость/точность: <code>eval-cheap-module-source-map</code> для dev, <code>source-map</code> (отдельный файл) для прода, <code>hidden-source-map</code> — карта генерируется, но комментарий не добавляется.</li>
    <li><strong>Безопасность</strong>: публичная карта с <code>sourcesContent</code> — это фактически публикация исходников, включая комментарии, внутренние URL и иногда ключи. Правильный вариант: <code>hidden-source-map</code>, загрузка карт в Sentry на этапе деплоя и удаление файлов с публичного CDN (или отдача только по IP/авторизации).</li>
    <li>Для сопоставления релиза и карт нужен стабильный идентификатор: Sentry использует <code>debug_id</code>/release, и его надо прокидывать в сборку, иначе стектрейсы не расшифруются.</li>
    <li>Отдельная боль — карты для стилей и для кода, прошедшего несколько трансформаций (TS → SWC → минификация): каждая ступень должна корректно сливать карты, иначе строки уезжают.</li></ul>`,
    tip: 'Связка hidden-source-map + загрузка карт в Sentry — стандартное продовое решение, называйте его сразу.' },

  { id: 'wx41',
    q: 'Как правильно организовать кеш-бастинг и деплой фронтенда?',
    a: `<p>Базовая схема: имена ассетов содержат <strong>хеш содержимого</strong> и отдаются с <code>Cache-Control: public, max-age=31536000, immutable</code>. HTML — точка входа — <strong>не кешируется</strong> (<code>no-cache</code> или короткий TTL с <code>must-revalidate</code>), потому что именно он ссылается на новые имена. Итог: релиз меняет только маленький HTML, вся статика переиспользуется.</p>
    <ul><li><strong>Порядок деплоя</strong>: сначала выложить новую статику, затем переключить HTML. Иначе пользователь получит HTML, ссылающийся на ещё не существующие файлы.</li>
    <li><strong>Не удалять старые ассеты сразу</strong>: у пользователя может быть открыта вкладка со старым HTML, и ленивый чанк подгрузится по старому имени. Держите 2–3 предыдущих релиза; ошибка <code>ChunkLoadError</code>/«Failed to fetch dynamically imported module» — прямое следствие удаления.</li>
    <li>Обработчик такой ошибки должен предлагать перезагрузку («вышла новая версия»), а не показывать белый экран.</li>
    <li>Хеш должен быть по <strong>содержимому</strong> (contenthash), а не по сборке, иначе кеш инвалидируется при каждом релизе; следите за стабильностью module id, иначе меняется хеш всех чанков.</li>
    <li>Атомарность: деплой через смену симлинка/префикса в S3 или через blue-green; инвалидация CDN только для HTML.</li></ul>`,
    code: `Cache-Control: public, max-age=31536000, immutable  # /assets/app.a1b2c3.js
Cache-Control: no-cache                              # /index.html`,
    tip: 'ChunkLoadError после деплоя — идеальная иллюстрация; обязательно упомяните хранение старых ассетов.' },

  { id: 'wx42',
    q: 'Что даёт CDN и что такое edge-рендеринг?',
    a: `<p>CDN — распределённая сеть узлов, отдающих контент из точки, географически близкой к пользователю. Выигрыш не только в расстоянии: терминация TLS рядом с пользователем экономит несколько RTT, соединение до origin уже прогрето, добавляется защита от DDoS и сжатие/оптимизация на лету.</p>
    <ul><li>Ключевые понятия: cache hit ratio, cache key (учитывайте <code>Vary</code> и query-параметры — маркетинговые UTM легко размывают кеш, их надо игнорировать в ключе), <code>stale-while-revalidate</code> и <code>stale-if-error</code>, инвалидация (purge) против версионирования имён.</li>
    <li><strong>Кешировать HTML на CDN</strong> — самый большой выигрыш в TTFB, но только для неперсонализированных страниц; для персонализации применяют ESI-подобную сборку, «дырки» на клиенте или сегментированный кеш по cookie в ключе.</li>
    <li><strong>Edge-функции</strong> (Cloudflare Workers, Vercel Edge, Fastly Compute) выполняют код в узле: A/B-разделение, геолокация, редиректы, авторизация, персонализация заголовков, streaming SSR. Ограничения — маленький рантайм (не Node), лимиты по CPU и памяти, отсутствие долгих соединений и большая цена «холодного» обращения к БД, если она в одном регионе.</li>
    <li>Практическое правило: на edge — то, что быстро и не требует данных; всё, что ходит в БД, часто выгоднее держать в регионе рядом с БД, иначе выигрыш от близости съедается round-trip-ами.</li></ul>`,
    tip: 'Замечание про edge-функцию, которая ходит в далёкую БД и теряет весь выигрыш, — зрелый архитектурный аргумент.' },

  { id: 'wx43',
    q: 'Как выстроить мониторинг ошибок фронтенда?',
    a: `<p>Ловим: <code>window.onerror</code>, <code>unhandledrejection</code>, ошибки в React error boundary, ошибки загрузки ресурсов (событие <code>error</code> в фазе захвата), нарушения CSP через <code>report-to</code>, а также <code>SecurityPolicyViolationEvent</code>.</p>
    <p>Что делает мониторинг полезным, а не шумным:</p>
    <ul><li><strong>Source maps</strong>, загруженные с привязкой к релизу, — без них стектрейс бесполезен.</li>
    <li><strong>Релиз и версия</strong> в каждом событии плюс маркировка деплоя — так видно регрессию сразу после выката.</li>
    <li><strong>Группировка и fingerprinting</strong>: без настройки одна ошибка расползается на сотни групп по разным сообщениям.</li>
    <li><strong>Фильтрация шума</strong>: расширения браузера, ошибки из <code>chrome-extension://</code>, «Script error.» от кросс-доменных скриптов без <code>crossorigin</code>, ResizeObserver loop, отменённые запросы при уходе со страницы, боты. Без этого команда перестаёт смотреть на алерты.</li>
    <li><strong>Контекст</strong>: breadcrumbs, user id (с учётом приватности), тип устройства, сеть, feature-флаги — именно контекст позволяет воспроизвести.</li>
    <li><strong>Сэмплирование</strong> трейсов и session replay, чтобы не разорить бюджет; алерт по <strong>доле</strong> сессий с ошибкой, а не по абсолютному числу.</li></ul>
    <p>И главное — процесс: у алерта должен быть владелец и SLA, иначе Sentry превращается в свалку.</p>`,
    tip: 'Отдельно упомяните «Script error.» и необходимость crossorigin на скриптах — это частая слепая зона.' },

  { id: 'wx44',
    q: 'Как использовать feature flags и canary-выкладку на фронтенде?',
    a: `<p>Флаги отделяют <strong>деплой</strong> от <strong>релиза</strong>: код уже в проде, но включён для 1% или для внутренней команды. Виды: release toggles (временные), experiment toggles (A/B), ops toggles (kill switch для тяжёлой фичи), permission toggles (доступ по тарифу).</p>
    <ul><li><strong>Canary</strong>: выкатываем на 1% → 5% → 25% → 100%, следя за метриками ошибок и производительности; при регрессе — мгновенный откат флага без деплоя. Это главное преимущество перед откатом релиза.</li>
    <li>Фронтендовая специфика: значение флага должно быть известно <strong>до первого рендера</strong>, иначе получаем мигание интерфейса и сдвиг макета. Решения: получать флаги на сервере при SSR и инлайнить в HTML, или держать локальный кеш последних значений с мгновенным стартом.</li>
    <li>Бандл: код обеих веток попадает в бандл. Для крупных фич — динамический импорт под флагом; для мёртвых веток — удаление на этапе сборки (compile-time флаги).</li>
    <li>Дисциплина: у флага есть владелец и срок жизни, иначе через год их сотни и комбинаторика становится непроверяемой. Заводите задачу на удаление вместе с созданием флага.</li>
    <li>Безопасность: клиентский флаг не защищает данные — проверка прав всегда на сервере, а сам список флагов не должен раскрывать неанонсированные фичи.</li></ul>`,
    tip: 'Требование «флаг должен быть известен до первого рендера» — специфическая фронтендовая деталь, её оценят.' },

  { id: 'wx45',
    q: 'Почему A/B-тесты портят CLS и как это исправить?',
    a: `<p>Классическая схема с внешним скриптом-редактором (Optimizely, VWO, GTM-эксперименты) работает так: страница рендерится в контрольном варианте, затем асинхронный скрипт применяет изменения и переставляет DOM. Пользователь видит «мигание оригинала» (FOOC) и получает <strong>сдвиг макета</strong> — прямой удар по CLS, а тяжёлый синхронный скрипт-антифликер ещё и по LCP и TBT.</p>
    <p>Типовое «лечение» — anti-flicker snippet, скрывающий <code>body</code> до применения. Это убирает мигание, но откладывает FCP и LCP на всё время загрузки скрипта (иногда секунды), а при его сбое — на таймаут. То есть проблему меняют на худшую.</p>
    <p>Правильные подходы:</p>
    <ul><li><strong>Server-side или edge-эксперименты</strong>: вариант выбирается до отдачи HTML, браузер получает уже финальную разметку — ни мигания, ни сдвига. Требует учёта кеша (вариант в cache key) и стабильного бакетирования по cookie.</li>
    <li>Изменения через <strong>CSS-класс на <code>html</code></strong>, проставленный инлайновым скриптом в head (варианты уже в CSS) — быстрый компромисс без внешнего скрипта.</li>
    <li>Резервировать место под изменяемый блок (<code>min-height</code>, <code>aspect-ratio</code>), чтобы даже поздняя подмена не двигала соседей.</li>
    <li>Измерять CWV <strong>в разрезе вариантов</strong>: эксперимент, выигравший по конверсии, но ухудшивший LCP, часто проигрывает в долгую.</li></ul>`,
    tip: 'Скажите, что anti-flicker snippet лечит симптом ценой LCP — это ровно тот компромисс, который ждут услышать.' }
];
